    .then(featured => {
      dispatch({ type: 'FEATURED_IMG_OK', v: featured });
      const sightings = buildSightingsFromFeatured(featured);
      if (sightings.length) dispatch({ type: 'SIGHT_OK', v: sightings });
      else dispatch({ type: 'SIGHT_ERR', v: 'No sightings with GPS coordinates found.' });
